it('the production account-bound review transport carries the exact typed view and genuine financial resolution through SQL-backed HTTP',async()=>{
 const config={apiUrl:'https://api.test',publishableKey:'sb_publishable_test_only'},handler=createOrderReviewHandler({origins:new Set([origin]),store:createOrderReviewStore('https://database.test',config.publishableKey,'sb_secret_test_only',commandTransport())}),send:typeof fetch=async(url,init)=>{const headers=new Headers(init?.headers);headers.set('Origin',origin);return handler(new Request(url,{...init,headers}));},remote=createCloudOrderReviewRemote(config,testCommandAccount(config,async()=>'user.1.signature'),{businessId:source.snapshot.business.id,outletId:source.snapshot.outlet.id,actorId:source.snapshot.owner.id},send),packet:OrderReviewRequest={id:newInboxId(),replacementId:newInboxId(),command:pay(),sourceHash:'a'.repeat(64),sourceJson:JSON.stringify({source:literal,total:2500})};
 const prepared=await remote.prepare(packet);expect(prepared.done).toBe(false);if(prepared.done)throw Error('Expected review');expect(prepared.review.proposal).toMatchObject({enabled:true,total:2500});assertCommandReceipt(prepared.review);
 const receipt=await remote.resolve({...packet,token:prepared.review.token,outcome:'replaced'});expect(receipt).toMatchObject({type:'command.resolved',commandId:packet.command.id,outcome:'replaced'});assertCommandReceipt(receipt);expect(await remote.prepare(packet)).toEqual({done:true,receipt});
});
it('the real review HTTP path exposes the current price and atomically applies the explicitly selected replacement',async()=>{
 const c=pay(),packet:OrderReviewRequest={id:newInboxId(),replacementId:newInboxId(),command:c,sourceHash:'a'.repeat(64),sourceJson:JSON.stringify({originalTotal:2500,source:literal})},edit:OrderCommand={...base(),type:'order.update',orderId:order.id,revision:order.revision,input:{...input(),lines:input().lines.map((line,index)=>({...line,id:order.lines[index].id,unitPrice:1400}))},newLineIds:[],settlement:null};await accepted(edit);
 const read=await reviewHttp(packet);expect(read.status,lastError+' '+await read.clone().text()).toBe(200);const body=await read.json() as {done:false;review:PreparedOrderReview};expect(body).toMatchObject({done:false,review:{commandId:c.id,current:{order:{total:2800}},proposal:{enabled:true,total:2800}}});expect(JSON.stringify(body)).not.toContain('contextJson');expect(JSON.stringify(body)).not.toContain('sb_secret_');
 const decision:OrderReviewDecision={...packet,token:body.review.token,outcome:'replaced'},result=await reviewHttp(decision);expect(result.status,lastError+' '+await result.clone().text()).toBe(200);const receipt=parseCommandResolutionReceipt(await result.json(),c);expect(receipt).toMatchObject({id:packet.id,commandId:c.id,outcome:'replaced',replacement:{id:packet.replacementId,receipt:{saleId:c.ids.saleId,total:2800}}});
 const retry=await reviewHttp(decision);expect(retry.status,lastError).toBe(200);expect(await retry.json()).toEqual(receipt);expect((await db.query('select * from public.sales where id=$1',[c.ids.saleId])).rows).toHaveLength(1);
});
it('the real HTTP withdrawal retains an explicit unposted-payment proof and its exact original source on retry',async()=>{
 const packet:OrderReviewRequest={id:newInboxId(),replacementId:newInboxId(),command:pay(),sourceHash:'a'.repeat(64),sourceJson:JSON.stringify({source:literal,total:2500})},read=await reviewHttp(packet),body=await read.json() as {review:PreparedOrderReview};expect(read.status,lastError).toBe(200);const before=await counts(),decision:OrderReviewDecision={...packet,token:body.review.token,outcome:'withdrawn'},resolved=await reviewHttp(decision);expect(resolved.status,lastError+' '+await resolved.clone().text()).toBe(200);const actual=await resolved.json();expect(actual).toMatchObject({type:'command.resolved',commandId:packet.command.id,outcome:'withdrawn',replacement:null});expect((await counts()).sales).toBe(before.sales);expect((await reviewHttp(decision)).status).toBe(200);expect((await counts()).events-before.events).toBe(1);
});
it('the HTTP commit refuses a reviewed-source race after its last read and never auto-refreshes consent',async()=>{
 const packet:OrderReviewRequest={id:newInboxId(),replacementId:newInboxId(),command:pay(),sourceHash:'a'.repeat(64),sourceJson:'{}'},read=await reviewHttp(packet),body=await read.json() as {review:PreparedOrderReview};expect(read.status,lastError).toBe(200);const before=await counts(),response=await reviewHttp({...packet,token:body.review.token,outcome:'replaced'},1,async()=>{await accepted(note(await readOrder()));});expect(response.status).toBe(409);expect((await counts()).sales).toBe(before.sales);expect((await db.query('select * from private.order_command_resolutions')).rows).toHaveLength(0);
});
