it('an audit failure rolls the order, money, receipt and every companion back together',async()=>{const c=create();c.settlement={id:newInboxId(),ids:finance(),input:{method:'credit',accountId:account.id}};const before=await counts();await db.exec("create function public.reject_order_audit() returns trigger language plpgsql as $$begin if new.command='khata.charge' then raise exception 'Fixture audit failure';end if;return new;end$$;create trigger reject_order_audit before insert on public.events for each row execute function public.reject_order_audit()");try{expect((await http(1,c)).status).toBe(503);expect(await counts()).toEqual(before);}finally{await db.exec('drop trigger reject_order_audit on public.events;drop function public.reject_order_audit()');}});
it.each(['member','assignment','role','identity','phone','confirmation','ban','deletion'] as const)('live %s revocation between preparation and completion rejects every write',async reason=>{const c=create(),before=await counts();let called=false;const r=await http(2,c,async()=>{called=true;const a=actors.find(a=>a.n===2)!;if(reason==='member')await db.query('update public.members set active=false where id=$1',[a.id]);if(reason==='assignment')await db.query('delete from public.member_outlets where member_id=$1',[a.id]);if(reason==='role')await db.query("update public.members set role='staff' where id=$1",[a.id]);if(reason==='identity')await db.query('update public.members set auth_user_id=$1 where id=$2',[uid(4),a.id]);if(reason==='phone')await db.query("update auth.users set phone='' where id=$1",[uid(2)]);if(reason==='confirmation')await db.query('update auth.users set phone_confirmed_at=null where id=$1',[uid(2)]);if(reason==='ban')await db.query("update auth.users set banned_until=now()+interval '1 hour' where id=$1",[uid(2)]);if(reason==='deletion')await db.query('update auth.users set deleted_at=now() where id=$1',[uid(2)]);});expect(called).toBe(true);expect(r.status).toBe(403);expect(await counts()).toEqual(before);});
it('a source race re-prepares the same IDs but a changed order revision requires review',async()=>{const c=create();let calls=0;await accepted(c);const p=pay(await readOrder(c.orderId)),response=await http(1,p,async()=>{if(calls++===0)await db.query('update public.customers set updated_at=updated_at+1 where id=$1',[customer.id]);});expect(response.status,lastError).toBe(200);expect(calls).toBe(2);expect((await readOrder(c.orderId)).payment.saleId).toBe(p.ids.saleId);const next=status(await readOrder(c.orderId)),r=await http(1,next,async()=>{await db.query('update public.orders set revision=revision+1 where id=$1',[c.orderId]);});expect(r.status).toBe(409);});
it('an unrelated selected source change permits at most three immutable attempts',async()=>{const c=create();let calls=0;const before=await counts(),r=await http(1,c,async()=>{calls++;await db.query('update public.customers set updated_at=updated_at+1 where id=$1',[customer.id]);});expect(calls).toBe(3);expect(r.status).toBe(409);expect(await counts()).toEqual(before);});
it('private tickets, receipts, raw writes and completion are denied to ordinary users',async()=>{for(const q of ['select * from private.order_write_tickets','select * from private.shop_command_receipts','update public.orders set revision=revision+1','select public.finish_order_write($1,$2,$3)'])await expect(role(1,'authenticated',q,q.includes('$1')?[newInboxId(),'x'.repeat(43),'[]']:[])).rejects.toMatchObject({code:'42501'});await expect(role(null,'service_role','select public.prepare_order_write($1,$2,$3,$4,$5,$6,$7)',[newInboxId(),newInboxId(),'order.create',order.outletId,'{}','a'.repeat(64),Date.now()])).rejects.toMatchObject({code:'42501'});});
it('ticket expiry and an incorrect opaque proof reject without changing any row',async()=>{const c=create(),p=await prepare(c),before=await counts();await expect(role(null,'service_role','select public.finish_order_write($1,$2,$3)',[p.ticketId,'x'.repeat(43),'[]'])).rejects.toMatchObject({code:'PT409'});await db.query('update private.order_write_tickets set expires_at=0 where id=$1',[p.ticketId]);await expect(finish(p,c)).rejects.toMatchObject({code:'PT409'});expect(await counts()).toEqual(before);});
it('the live completion clock rejects expired payment undo even with a forged preparation clock',async()=>{const p=pay();p.occurredAt=Date.now()-601000;await accepted(p);const c=undoPayment(await readOrder());c.occurredAt=p.occurredAt+2;const prepared=await prepare(c),forged={...prepared,at:p.occurredAt+1},fields=orderWriteFields(forged,c,prepared.ticketId as string);await expect(role(null,'service_role','select public.finish_order_write($1,$2,$3)',[fields.p_ticket_id,fields.p_token,JSON.stringify(fields.p_records)])).rejects.toMatchObject({code:'PT409',message:expect.stringMatching(/within ten minutes/)});});
it('the live completion clock independently rejects expired refund undo',async()=>{await accepted(pay());await accepted(status(await readOrder(),'cancelled'));const ref=refund(await readOrder());await accepted(ref);await db.query('update public.order_refunds set created_at=$1 where id=$2',[Date.now()-601000,ref.ids.refundId]);const original=await saved<OrderRefund>('orderRefunds',ref.ids.refundId),c=undoRefund(await readOrder(),original);c.occurredAt=original.createdAt+2;const p=await prepare(c),fields=orderWriteFields({...p,at:original.createdAt+1},c,p.ticketId as string);await expect(role(null,'service_role','select public.finish_order_write($1,$2,$3)',[fields.p_ticket_id,fields.p_token,JSON.stringify(fields.p_records)])).rejects.toMatchObject({code:'PT409',message:expect.stringMatching(/within ten minutes/)});});
it('the complete 200-line maximum escaped order crosses only the admitted body path',async()=>{const c=create();c.input.sourceText='\0'.repeat(12000);c.input.lines=Array.from({length:200},()=>({name:'\0'.repeat(120),unit:'\0'.repeat(24),qty:0.5,unitPrice:245,note:'\0'.repeat(500),substitution:{from:'\0'.repeat(120),accepted:true}}));c.newLineIds=c.input.lines.map(()=>newInboxId());const bytes=new TextEncoder().encode(JSON.stringify(c)).length;expect(bytes).toBeGreaterThan(512000);expect(bytes).toBeLessThan(orderBodyLimit);expect((await http(1,c,undefined,null)).status).toBe(413);const r=await accepted(c),o=await readOrder(c.orderId);expect(r.total).toBe(24600);expect(o.lines.map(l=>l.id)).toEqual(c.newLineIds);expect(o.lines[199].note).toBe('\0'.repeat(500));},30000);
it('the larger body is never consumed before outlet authorization, and admitted families cannot be mixed',async()=>{let readers=0;const c=create(),req=new Request('https://api.test/commands',{method:'POST',headers:{Origin:origin,Authorization:'Bearer user.3.signature','Content-Type':'application/json',[orderBodyHeader]:c.outletId},body:JSON.stringify(c)});const original=req.body!.getReader.bind(req.body);Object.defineProperty(req.body,'getReader',{value:(...args:Parameters<ReadableStream['getReader']>)=>{readers++;return original(...args);}});const r=await createCommandsHandler({origins:new Set([origin]),store:store()})(req);expect(r.status).toBe(403);expect(readers).toBe(0);req.headers.set('X-Mise-Purchase-Record',c.outletId);expect((await createCommandsHandler({origins:new Set([origin]),store:store()})(req)).status).toBe(400);});
it.each(['extra','future','duplicate','fraction','wrong-source'] as const)('strict %s input cannot write or allocate a receipt',async bad=>{const c=create(),before=await counts();let value:unknown=c;if(bad==='extra')value={...c,actorId:source.snapshot.owner.id};if(bad==='future')c.occurredAt=Date.now()+360000;if(bad==='duplicate')c.newLineIds=[c.id];if(bad==='fraction')c.input.discount=0.5;if(bad==='wrong-source')c.input.source='link' as OrderInput['source'];const r=await http(1,value as OrderCommand);expect([400,409]).toContain(r.status);expect(await counts()).toEqual(before);});
it('receipt parsing rejects extra fields, mismatched companion IDs and incorrect revisions',async()=>{const c=create(),r=await accepted(c);for(const wrong of [{...r,extra:1},{...r,revision:r.revision!+1},{...r,noteId:newInboxId()},{...r,entryId:newInboxId()},{...r,orderId:newInboxId()},{...r,undoOf:newInboxId()}])expect(()=>parseOrderCommandReceipt(wrong,c)).toThrow();expect(parseOrderCommand(JSON.parse(JSON.stringify(c)))).toEqual(parseOrderCommand(c));});
it.each(['tenant','creator','event-id','total','column','actor','audit-command','sale-id','missing-entry','missing-sale','missing-audit','duplicate','table'] as const)('service payload %s tampering cannot partially commit an order transaction',async tamper=>{const c=create();c.settlement={id:newInboxId(),ids:finance(),input:{method:'credit',accountId:account.id}};const p=await prepare(c),before=await counts();await expect(finish(p,c,rows=>{const root=rows.find(r=>r.table==='orders')!,audit=rows.find(r=>r.table==='events')!,sale=rows.find(r=>r.table==='sales')!;if(tamper==='tenant')root.values.outlet_id=branch.snapshot.outlet.id;if(tamper==='creator')root.values.created_by=actors.find(a=>a.n===2)!.id;if(tamper==='event-id')root.values.event_id=newInboxId();if(tamper==='total')root.values.total=1;if(tamper==='column')root.values.extra='no';if(tamper==='actor')audit.values.actor_id=actors.find(a=>a.n===2)!.id;if(tamper==='audit-command')audit.values.command='sale.record';if(tamper==='sale-id')sale.values.id=newInboxId();if(tamper==='missing-entry'){rows.splice(rows.findIndex(r=>r.table==='credit_entries'),1);rows.splice(rows.findIndex(r=>r.table==='events'&&r.values.id===c.settlement!.ids.creditEventId),1);}if(tamper==='missing-sale'){rows.splice(rows.findIndex(r=>r.table==='sales'),1);rows.splice(rows.findIndex(r=>r.table==='events'&&r.values.id===c.settlement!.ids.saleEventId),1);}if(tamper==='missing-audit')rows.splice(rows.findIndex(r=>r.table==='events'&&r.values.id===c.id),1);if(tamper==='duplicate')rows.push(root);if(tamper==='table')rows.push({table:'customers',values:{}});})).rejects.toMatchObject({code:'22023'});expect(await counts()).toEqual(before);});
it('a cross-outlet order identity inserted after preparation can never be overwritten',async()=>{const c=create();let called=false;const response=await http(1,c,async()=>{if(called)return;called=true;const r=saveOrderCommand({...input(),customerId:branchCustomer.id,phone:branchCustomer.phone!},{setup:branch.snapshot,items:[],customer:branchCustomer,sequence:2},null,0,c.occurredAt,kind=>kind==='order'?c.orderId:newInboxId());await insert([encodeCommandRecord('orders',r.order,source.snapshot.business.id),encodeCommandRecord('events',r.event,source.snapshot.business.id)]);});expect(called).toBe(true);expect(response.status).toBe(409);expect((await readOrder(c.orderId)).outletId).toBe(branch.snapshot.outlet.id);});
it('current credit consent is exact and must be renewed after a balance change',async()=>{await db.query('update public.credit_accounts set credit_limit=1000 where id=$1',[account.id]);expect((await http(1,pay(order,true))).status).toBe(409);const wrong=pay(order,true);wrong.input.confirmation={balance:1,limit:1000};expect((await http(1,wrong)).status).toBe(409);const c=pay(order,true);c.input.confirmation={balance:0,limit:1000};let changed=false;const response=await http(1,c,async()=>{if(changed)return;changed=true;const r=chargeCreditCommand(100,{setup:source.snapshot,customer,account,entries:[]},{note:'Other current charge'},Date.now()-500);await insert([encodeCommandRecord('creditEntries',r.entry,source.snapshot.business.id),encodeCommandRecord('events',r.event,source.snapshot.business.id)]);});expect(response.status).toBe(409);expect(changed).toBe(true);const reviewed=pay(order,true);reviewed.input.confirmation={balance:100,limit:1000};await accepted(reviewed);expect((await readOrder()).payment.status).toBe('credited');});
it('literal historical wallet JSON remains usable without SQL field extraction',async()=>{await db.query('update public.orders set payment=$1 where id=$2',[JSON.stringify({method:'wallet',wallet:literal,status:'pending'}),order.id]);const c=pay();c.input={method:'wallet',wallet:literal};await accepted(c);const o=await readOrder();expect((await saved<Sale>('sales',c.ids.saleId)).methodName).toBe(literal);await accepted(undoPayment(o));expect((await readOrder()).payment.wallet).toBe(literal);});
it('payment audit after-images exactly match committed records and the server admission clock',async()=>{const c=pay(order,true),r=await accepted(c),o=await readOrder(),s=await saved<Sale>('sales',c.ids.saleId),e=(await db.query<{data:string}>('select row_to_json(e)::text data from public.credit_entries e where id=$1',[c.ids.entryId])).rows[0],entry=decodeCommandRecord('creditEntries',JSON.parse(e.data));const audits=(await db.query<{id:string;after_data:unknown;at:number}>('select id,after_data,at from public.events where id=any($1::text[])',[[c.id,c.ids.saleEventId,c.ids.creditEventId]])).rows;for(const a of audits){expect(a.at).toBe(r.at);expect(a.after_data).toEqual(JSON.parse(JSON.stringify(a.id===c.id?o:a.id===c.ids.saleEventId?s:entry)));}});
it('legacy future creation clocks survive order history updates',async()=>{const future=Date.now()+60000;await db.query('update public.orders set created_at=$1,updated_at=$1 where id=$2',[future,order.id]);const c:OrderCommand={...base(),type:'order.note',orderId:order.id,revision:1,noteId:newInboxId(),text:literal},r=await accepted(c);expect(await readOrder()).toMatchObject({createdAt:future,updatedAt:future});expect(r.updatedAt).toBe(future);});
it('only the three defined large-command families receive a larger read allowance',async()=>{const c=create();const foreign={...c,outletId:branch.snapshot.outlet.id};expect((await http(1,foreign,undefined,c.outletId)).status).toBe(400);const note:OrderCommand={...base(),type:'order.note',orderId:order.id,revision:1,noteId:newInboxId(),text:literal};expect((await http(1,note,undefined,c.outletId)).status).toBe(400);});
it('pending order plans cannot be replaced even with a repeated claimed hash',async()=>{const c=create(),p=await prepare(c),plan=orderWritePlan(c);plan.newLineIds=[newInboxId()];await expect(role(1,'authenticated','select public.prepare_order_write($1,$2,$3,$4,$5,$6,$7)',[c.id,newInboxId(),c.type,c.outletId,JSON.stringify(plan),await orderFingerprint(c),c.occurredAt])).rejects.toMatchObject({code:'23505'});await finish(p,c);});
it('the exact thirteen-action hosted role fixture rolls every fictional identity and record back',async()=>{const before=await counts(),results=await db.exec(await orderHostedProofSql()),row=results.at(-1)!.rows[0] as {proof:Record<string,unknown>;auth_rows:number;business_rows:number;ticket_rows:number};expect(row).toMatchObject({auth_rows:0,business_rows:0,ticket_rows:0,proof:{commands:13,receipts:13,audits:23,replayExact:true,creditReversed:true,literalUnicodeRetained:true,orderHistoryRetained:true,walletRestored:true,refundVoided:true,ordinaryCompletionDenied:true,privateReadsDenied:true,otherIdentityDenied:true}});expect(await counts()).toEqual(before);});
it('a caller is capped at 100 live preparations without retaining duplicated pasted bodies',async()=>{for(let n=0;n<100;n++)await prepare(create());await expect(prepare(create())).rejects.toMatchObject({code:'PT429'});const row=(await db.query<{tickets:number;omitted:boolean}>("select count(*)::int tickets,bool_and(not(plan ? 'intentJson')) omitted from private.order_write_tickets")).rows[0];expect(row).toEqual({tickets:100,omitted:true});},30000);
